import React, { useState, useEffect } from "react";
import styles from "./Banner.module.css";
import fetchMovie, { requests } from "../../../movieList";

function Banner() {
  const [movie, setMovie] = useState([]);
  const [banner, setBanner] = useState({});

  useEffect(() => {
    async function loadMovie() {
      const data = await fetchMovie(requests.fetchNetflixOriginals);
      setMovie(data);
    }
    loadMovie();
  }, []);

  setBanner(movie.results[Math.floor(Math.random() * movie.results.length)]);
  console.log(movie);
  console.log(banner);

  return (
    <div>
      <img src="" alt="" />
    </div>
  );
}

export default Banner;
